// Keep this preview texture local and render the same source on native and web.
// Run after replacing either bundled preview illustration.
const {readFile, writeFile} = require('node:fs/promises');
const {join} = require('node:path');
const sharp = require('sharp');

(async () => {
  const directory = join(__dirname, '../src/ui/images');
  const image = await readFile(join(directory, 'library-preview.jpg'));
  const {width, height} = await sharp(image).metadata();
  await writeFile(join(directory, 'libraryPreview.ts'),
    '// Generated by scripts/generate-library-preview.cjs from library-preview.jpg.\n' +
    `export const libraryPreviewAtlas = ${JSON.stringify({uri: `data:image/jpeg;base64,${image.toString('base64')}`, width, height})} as const;\n`);
  const cover = await readFile(join(directory, 'night-library-cover.jpg'));
  const coverSize = await sharp(cover).metadata();
  await writeFile(join(directory, 'nightLibraryCover.ts'),
    '// Generated by scripts/generate-library-preview.cjs from night-library-cover.jpg.\n' +
    `export const nightLibraryCover = ${JSON.stringify({uri: `data:image/jpeg;base64,${cover.toString('base64')}`, width: coverSize.width, height: coverSize.height})} as const;\n`);
  const gallery = [];
  for (const name of ['night-library-reading.jpg', 'night-library-room.jpg']) {
    const bytes = await readFile(join(directory, name));
    const size = await sharp(bytes).metadata();
    gallery.push({uri: `data:image/jpeg;base64,${bytes.toString('base64')}`, width: size.width, height: size.height});
  }
  await writeFile(join(directory, 'galleryArtwork.ts'), '// Generated by scripts/generate-library-preview.cjs.\n' +
    `export const galleryArtwork = ${JSON.stringify(gallery)} as const;\n`);
})().catch(error => {console.error(error); process.exitCode = 1;});
